//! Unicode 16.0 NFC/NFD/NFKC/NFKD normalization.
//!
//! Tables are auto-generated from UCD 16.0 (see CCC, decomposition, and
//! composition pair arrays at the bottom). Hot path uses SoA sorted arrays
//! with binary search — no hash maps, no allocations except the output
//! buffers.

const std = @import("std");

pub const Form = enum { nfc, nfd, nfkc, nfkd };

// ---- Hangul algorithmic constants (TR15 / Unicode 3.12) ----
const S_BASE: u21 = 0xAC00;
const L_BASE: u21 = 0x1100;
const V_BASE: u21 = 0x1161;
const T_BASE: u21 = 0x11A7;
const L_COUNT: u21 = 19;
const V_COUNT: u21 = 21;
const T_COUNT: u21 = 28;
const N_COUNT: u21 = 588; // V_COUNT * T_COUNT
const S_COUNT: u21 = 11172; // L_COUNT * N_COUNT
const S_END: u21 = S_BASE + S_COUNT - 1;

fn isHangulSyllable(cp: u21) bool {
    return cp >= S_BASE and cp <= S_END;
}

fn isHangulL(cp: u21) bool {
    return cp >= L_BASE and cp < L_BASE + L_COUNT;
}

fn isHangulV(cp: u21) bool {
    return cp >= V_BASE and cp < V_BASE + V_COUNT;
}

fn isHangulT(cp: u21) bool {
    return cp > T_BASE and cp < T_BASE + T_COUNT;
}

// ---- Public API ----

/// Combining class of cp. 0 if unmapped.
pub fn ccc(cp: u21) u8 {
    // Binary search ccc_entries by cp
    var lo: usize = 0;
    var hi: usize = ccc_entries.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const e = ccc_entries[mid];
        if (e.cp == cp) return e.ccc;
        if (e.cp < cp) lo = mid + 1 else hi = mid;
    }
    return 0;
}

/// Canonical decomposition. Slice may be empty (no decomposition);
/// caller treats empty as "cp decomposes to itself".
pub fn decomposeCanonical(cp: u21) []const u21 {
    if (isHangulSyllable(cp)) return &.{}; // algorithmic
    var lo: usize = 0;
    var hi: usize = canon_index.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const e = canon_index[mid];
        if (e.cp == cp) return canon_data[e.start .. e.start + e.len];
        if (e.cp < cp) lo = mid + 1 else hi = mid;
    }
    return &.{};
}

/// Compatibility decomposition (includes canonical). Empty = self.
pub fn decomposeCompat(cp: u21) []const u21 {
    if (isHangulSyllable(cp)) return &.{};
    var lo: usize = 0;
    var hi: usize = compat_index.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const e = compat_index[mid];
        if (e.cp == cp) return compat_data[e.start .. e.start + e.len];
        if (e.cp < cp) lo = mid + 1 else hi = mid;
    }
    return &.{};
}

/// Compose two codepoints into a primary composite. Returns null if not
/// composable or if the result is excluded.
pub fn compose(a: u21, b: u21) ?u21 {
    // Hangul L+V -> LV
    if (isHangulL(a) and isHangulV(b)) {
        const l_idx: u21 = a - L_BASE;
        const v_idx: u21 = b - V_BASE;
        return S_BASE + (l_idx * V_COUNT + v_idx) * T_COUNT;
    }
    // Hangul LV+T -> LVT
    if (isHangulSyllable(a) and isHangulT(b)) {
        // a must be LV (no trailing): (a - S_BASE) % T_COUNT == 0
        if ((a - S_BASE) % T_COUNT == 0) {
            return a + (b - T_BASE);
        }
    }
    // Table lookup: binary search by (a, b)
    var lo: usize = 0;
    var hi: usize = comp_pairs.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const e = comp_pairs[mid];
        if (e.a == a and e.b == b) return e.result;
        if (e.a < a or (e.a == a and e.b < b)) lo = mid + 1 else hi = mid;
    }
    return null;
}

/// Normalize UTF-8 `input` to `form`. Caller owns returned bytes.
///
/// Fast path: skips the per-codepoint source-offset array that
/// `normalizeWithOrigin` threads through every stage. For a 10 MB input
/// that's a 10-40 MB allocation + byte-by-byte src bookkeeping we don't
/// need when the caller only wants the bytes. The encoder hot path on
/// `Pipeline.encodeText` (which discarded the origin map immediately
/// after) was paying that cost on every encode — see 1.14 TM Monster
/// regression fix in bench/RESULTS.md.
pub fn normalize(allocator: std.mem.Allocator, form: Form, input: []const u8) ![]u8 {
    const use_compat = (form == .nfkc or form == .nfkd);
    const do_compose = (form == .nfc or form == .nfkc);

    // === NF-stable run fast path ===
    //
    // The reference TR15 algorithm decodes the whole input to
    // codepoints, decomposes/reorders/composes, then re-encodes. For
    // a 10 MB input that's a 40 MB u21 round-trip even when most
    // codepoints don't decompose at all. The optimization below
    // streams the input in runs of NF-stable codepoints:
    //
    //   * A run of bytes is NF-stable for NFD/NFKD if every codepoint
    //     has no decomposition AND zero combining class.
    //   * For NFC/NFKC the same conditions hold BUT we must also know
    //     the codepoint can't compose with the NEXT codepoint. The
    //     safe rule used here: a stable cp must be followed by another
    //     stable cp (so neither can be a non-starter that the current
    //     starter could absorb). We implement this with a one-cp
    //     lookahead: when we encounter a non-stable cp we back the
    //     current stable run up by one codepoint, pulling the prior
    //     starter into the dirty region so a `starter+nonstarter`
    //     adjacency always lives entirely inside a dirty flush.
    //
    // For ASCII codepoints the decomposition table is empty and ccc
    // is 0, so this is exactly the ASCII fast path. For non-ASCII
    // codepoints we still get the win on any cp that is NF-stable
    // (CJK ideographs, most punctuation, etc.). Non-stable cps fall
    // back to the codepoint round-trip for the surrounding "dirty"
    // region. This is the dominant cost in TM Monster normalize on
    // the 1.14 regression fix — the test corpus is 63% non-ASCII
    // but ~99% NF-stable bytes.
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    try out.ensureTotalCapacity(allocator, input.len + input.len / 8);

    var buf: std.ArrayList(u21) = .empty;
    defer buf.deinit(allocator);

    var i: usize = 0;
    var stable_run_start: usize = 0;
    var dirty_run_start: ?usize = null;
    // For NFC/NFKC: track the start of the last stable codepoint
    // inside the current stable run so we can retract it into the
    // dirty region if the next cp turns out to be non-stable. -1
    // means "no prior stable cp in this run" (i.e. the run hasn't
    // started yet or we just flushed).
    var last_stable_cp_start: usize = 0;
    var last_stable_cp_present: bool = false;

    // Helper: drain `dirty_run_start..end` as a codepoint round-trip.
    const flushDirty = struct {
        fn call(
            alloc: std.mem.Allocator,
            buf_: *std.ArrayList(u21),
            out_: *std.ArrayList(u8),
            slice: []const u8,
            use_compat_: bool,
            do_compose_: bool,
        ) !void {
            buf_.clearRetainingCapacity();
            var j: usize = 0;
            while (j < slice.len) {
                const b0 = slice[j];
                const seq_len = std.unicode.utf8ByteSequenceLength(b0) catch {
                    try buf_.append(alloc, @as(u21, b0));
                    j += 1;
                    continue;
                };
                if (j + seq_len > slice.len) {
                    try buf_.append(alloc, @as(u21, b0));
                    j += 1;
                    continue;
                }
                const cp = std.unicode.utf8Decode(slice[j .. j + seq_len]) catch {
                    try buf_.append(alloc, @as(u21, b0));
                    j += 1;
                    continue;
                };
                j += seq_len;
                try decomposeInto(alloc, buf_, cp, use_compat_);
            }
            canonicalReorder(buf_.items);
            if (do_compose_) composeInPlace(buf_);
            var enc: [4]u8 = undefined;
            for (buf_.items) |cp| {
                if (cp > 0x10FFFF) {
                    if (cp <= 0xFF) try out_.append(alloc, @intCast(cp));
                    continue;
                }
                const n = std.unicode.utf8Encode(@intCast(cp), &enc) catch {
                    const r = std.unicode.utf8Encode(0xFFFD, &enc) catch unreachable;
                    try out_.appendSlice(alloc, enc[0..r]);
                    continue;
                };
                try out_.appendSlice(alloc, enc[0..n]);
            }
        }
    }.call;

    while (i < input.len) {
        const b0 = input[i];

        // Decode this codepoint length.
        var seq_len: usize = 1;
        var cp_decoded: bool = true;
        var cp: u21 = b0;
        if (b0 < 0x80) {
            seq_len = 1;
            cp = b0;
        } else {
            seq_len = std.unicode.utf8ByteSequenceLength(b0) catch blk: {
                cp_decoded = false;
                break :blk 1;
            };
            if (cp_decoded) {
                if (i + seq_len > input.len) {
                    cp_decoded = false;
                    seq_len = 1;
                } else {
                    cp = std.unicode.utf8Decode(input[i .. i + seq_len]) catch blk: {
                        cp_decoded = false;
                        seq_len = 1;
                        break :blk 0;
                    };
                }
            }
        }

        // Classify stability for the requested form.
        //   * ccc must be 0 (otherwise canonical reordering may move it).
        //   * decomposition must be empty.
        //   * Hangul L/V/T jamo (U+1100..U+11FF) intentionally treated
        //     as dirty so L+V composition under NFC still fires.
        //   * Invalid UTF-8 → dirty.
        var is_stable: bool = false;
        if (cp_decoded) {
            if (cp < 0x80) {
                is_stable = true; // ASCII is NF-stable in all four forms.
            } else {
                const decomp = if (use_compat) decomposeCompat(cp) else decomposeCanonical(cp);
                const c = ccc(cp);
                // Algorithmic Hangul:
                //   * Syllables (U+AC00..U+D7A3) decompose algorithmically
                //     to L+V[+T] jamo, so they're never NF-stable.
                //   * L/V/T jamo (U+1100..U+11FF) and their compat blocks
                //     (U+A960..U+A97F, U+D7B0..U+D7FF) can compose under
                //     NFC. Conservatively treat all of them as dirty so
                //     the surrounding region is processed through the
                //     codepoint path.
                const is_hangul = isHangulSyllable(cp) or
                    (cp >= 0x1100 and cp <= 0x11FF) or
                    (cp >= 0xA960 and cp <= 0xA97F) or
                    (cp >= 0xD7B0 and cp <= 0xD7FF);
                is_stable = (c == 0 and decomp.len == 0 and !is_hangul);
            }
        }

        if (is_stable) {
            if (dirty_run_start) |ds| {
                // Flush prior dirty region before re-entering stable.
                try flushDirty(allocator, &buf, &out, input[ds..i], use_compat, do_compose);
                dirty_run_start = null;
                stable_run_start = i;
                last_stable_cp_present = false;
            }
            // Remember this stable cp's start so we can retract it
            // into a dirty region if the NEXT cp turns out non-stable
            // under NFC/NFKC composition rules.
            last_stable_cp_start = i;
            last_stable_cp_present = true;
            i += seq_len;
            continue;
        }

        // Non-stable codepoint: enter / extend dirty span.
        if (dirty_run_start == null) {
            // Compute the stable-run-end boundary, retracting one
            // codepoint under NFC/NFKC (composition lookahead).
            var stable_end = i;
            if (do_compose and last_stable_cp_present) {
                stable_end = last_stable_cp_start;
            }
            if (stable_end > stable_run_start) {
                try out.appendSlice(allocator, input[stable_run_start..stable_end]);
            }
            dirty_run_start = stable_end;
            last_stable_cp_present = false;
        }
        i += seq_len;
    }

    // Tail flush.
    if (dirty_run_start) |ds| {
        try flushDirty(allocator, &buf, &out, input[ds..i], use_compat, do_compose);
    } else if (i > stable_run_start) {
        try out.appendSlice(allocator, input[stable_run_start..i]);
    }

    return out.toOwnedSlice(allocator);
}

/// Normalize + produce a per-output-byte map back to the originating
/// codepoint's start offset in the original input. See
/// `normalizer.NormalizationResult` for the public type. Convention:
/// every output byte's `origin[i]` is the byte offset (in `input`) of
/// the start of the codepoint that produced it. For multi-byte
/// expansions (NFD, ligature unwrap, Hangul syllable decomposition),
/// all expanded output bytes share the source codepoint's start.
pub fn normalizeWithOrigin(
    allocator: std.mem.Allocator,
    form: Form,
    input: []const u8,
) !@import("normalizer.zig").NormalizationResult {
    const use_compat = (form == .nfkc or form == .nfkd);
    const do_compose = (form == .nfc or form == .nfkc);

    var buf: std.ArrayList(u21) = .empty;
    defer buf.deinit(allocator);
    var src: std.ArrayList(u32) = .empty;
    defer src.deinit(allocator);
    try buf.ensureTotalCapacity(allocator, input.len);
    try src.ensureTotalCapacity(allocator, input.len);

    // Step 1: decompose. Walk UTF-8, recursively expand each cp; track
    // the source byte offset alongside each emitted codepoint.
    var i: usize = 0;
    while (i < input.len) {
        const src_off: u32 = @intCast(i);
        const b0 = input[i];
        const seq_len = std.unicode.utf8ByteSequenceLength(b0) catch {
            // Invalid lead byte — pass through as raw byte.
            try buf.append(allocator, @as(u21, b0));
            try src.append(allocator, src_off);
            i += 1;
            continue;
        };
        if (i + seq_len > input.len) {
            try buf.append(allocator, @as(u21, b0));
            try src.append(allocator, src_off);
            i += 1;
            continue;
        }
        const cp = std.unicode.utf8Decode(input[i .. i + seq_len]) catch {
            try buf.append(allocator, @as(u21, b0));
            try src.append(allocator, src_off);
            i += 1;
            continue;
        };
        i += seq_len;
        try decomposeIntoWithSrc(allocator, &buf, &src, cp, src_off, use_compat);
    }

    // Step 2: canonical reordering — must keep src offsets in lockstep.
    canonicalReorderWithSrc(buf.items, src.items);

    // Step 3: optional composition.
    if (do_compose) composeInPlaceWithSrc(&buf, &src);

    // Step 4: re-encode to UTF-8. Each output byte inherits the src
    // offset of the codepoint that produced it.
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    var origin: std.ArrayList(u32) = .empty;
    errdefer origin.deinit(allocator);
    try out.ensureTotalCapacity(allocator, buf.items.len * 4);
    try origin.ensureTotalCapacity(allocator, buf.items.len * 4);
    var enc: [4]u8 = undefined;
    for (buf.items, src.items) |cp, off| {
        if (cp > 0x10FFFF) {
            // Pass-through bytes from invalid UTF-8 (we stored them as cp <= 0xFF).
            if (cp <= 0xFF) {
                try out.append(allocator, @intCast(cp));
                try origin.append(allocator, off);
            }
            continue;
        }
        const n = std.unicode.utf8Encode(@intCast(cp), &enc) catch {
            // Surrogate or other invalid scalar — fall back to U+FFFD.
            const r = std.unicode.utf8Encode(0xFFFD, &enc) catch unreachable;
            try out.appendSlice(allocator, enc[0..r]);
            var k: usize = 0;
            while (k < r) : (k += 1) try origin.append(allocator, off);
            continue;
        };
        try out.appendSlice(allocator, enc[0..n]);
        var k: usize = 0;
        while (k < n) : (k += 1) try origin.append(allocator, off);
    }
    std.debug.assert(out.items.len == origin.items.len);
    const bytes = try out.toOwnedSlice(allocator);
    errdefer allocator.free(bytes);
    const orig_slice = try origin.toOwnedSlice(allocator);
    return .{ .bytes = bytes, .origin = orig_slice };
}

// ---- Internals ----

fn decomposeInto(
    allocator: std.mem.Allocator,
    buf: *std.ArrayList(u21),
    cp: u21,
    use_compat: bool,
) !void {
    if (isHangulSyllable(cp)) {
        const s_idx = cp - S_BASE;
        const l = L_BASE + s_idx / N_COUNT;
        const v = V_BASE + (s_idx % N_COUNT) / T_COUNT;
        const t = s_idx % T_COUNT;
        try buf.append(allocator, l);
        try buf.append(allocator, v);
        if (t != 0) try buf.append(allocator, T_BASE + t);
        return;
    }
    // Tables already hold fully recursive decomposition — no recursion needed.
    const d = if (use_compat) decomposeCompat(cp) else decomposeCanonical(cp);
    if (d.len == 0) {
        try buf.append(allocator, cp);
        return;
    }
    try buf.appendSlice(allocator, d);
}

/// Same as `decomposeInto` but pushes `src_off` once per emitted
/// codepoint into the parallel `src` array.
fn decomposeIntoWithSrc(
    allocator: std.mem.Allocator,
    buf: *std.ArrayList(u21),
    src: *std.ArrayList(u32),
    cp: u21,
    src_off: u32,
    use_compat: bool,
) !void {
    if (isHangulSyllable(cp)) {
        const s_idx = cp - S_BASE;
        const l = L_BASE + s_idx / N_COUNT;
        const v = V_BASE + (s_idx % N_COUNT) / T_COUNT;
        const t = s_idx % T_COUNT;
        try buf.append(allocator, l);
        try src.append(allocator, src_off);
        try buf.append(allocator, v);
        try src.append(allocator, src_off);
        if (t != 0) {
            try buf.append(allocator, T_BASE + t);
            try src.append(allocator, src_off);
        }
        return;
    }
    const d = if (use_compat) decomposeCompat(cp) else decomposeCanonical(cp);
    if (d.len == 0) {
        try buf.append(allocator, cp);
        try src.append(allocator, src_off);
        return;
    }
    try buf.appendSlice(allocator, d);
    var k: usize = 0;
    while (k < d.len) : (k += 1) try src.append(allocator, src_off);
}

// Stable sort each combining-mark run by ccc.
fn canonicalReorder(items: []u21) void {
    var i: usize = 0;
    while (i < items.len) {
        // Skip starters.
        while (i < items.len and ccc(items[i]) == 0) : (i += 1) {}
        // Find end of run (next starter or EOF).
        var j = i;
        while (j < items.len and ccc(items[j]) != 0) : (j += 1) {}
        if (j > i + 1) insertionSortByCcc(items[i..j]);
        i = j;
    }
}

fn insertionSortByCcc(slice: []u21) void {
    // Insertion sort is stable and fast on the short runs we expect.
    var i: usize = 1;
    while (i < slice.len) : (i += 1) {
        const x = slice[i];
        const xc = ccc(x);
        var j: usize = i;
        while (j > 0) {
            const yc = ccc(slice[j - 1]);
            if (yc <= xc) break;
            slice[j] = slice[j - 1];
            j -= 1;
        }
        slice[j] = x;
    }
}

/// Reorder + parallel src offsets. Swaps the src offset alongside each
/// codepoint move so origin tracking survives canonical reordering.
fn canonicalReorderWithSrc(items: []u21, src: []u32) void {
    std.debug.assert(items.len == src.len);
    var i: usize = 0;
    while (i < items.len) {
        while (i < items.len and ccc(items[i]) == 0) : (i += 1) {}
        var j = i;
        while (j < items.len and ccc(items[j]) != 0) : (j += 1) {}
        if (j > i + 1) insertionSortByCccWithSrc(items[i..j], src[i..j]);
        i = j;
    }
}

fn insertionSortByCccWithSrc(slice: []u21, src: []u32) void {
    std.debug.assert(slice.len == src.len);
    var i: usize = 1;
    while (i < slice.len) : (i += 1) {
        const x = slice[i];
        const xs = src[i];
        const xc = ccc(x);
        var j: usize = i;
        while (j > 0) {
            const yc = ccc(slice[j - 1]);
            if (yc <= xc) break;
            slice[j] = slice[j - 1];
            src[j] = src[j - 1];
            j -= 1;
        }
        slice[j] = x;
        src[j] = xs;
    }
}

/// Compose + parallel src offsets. When two codepoints compose, the
/// resulting composite inherits the source offset of the STARTER
/// (the codepoint at `starter_pos`) — the most informative choice for
/// downstream offset translation, since the combining mark "decorates"
/// the starter character.
fn composeInPlaceWithSrc(buf: *std.ArrayList(u21), src: *std.ArrayList(u32)) void {
    const items = buf.items;
    const src_items = src.items;
    std.debug.assert(items.len == src_items.len);
    if (items.len == 0) return;
    var out_len: usize = 0;
    var starter_pos: ?usize = null;
    var last_ccc: i16 = -1;
    var i: usize = 0;
    while (i < items.len) : (i += 1) {
        const cp = items[i];
        const sof = src_items[i];
        const cp_ccc: i16 = @intCast(ccc(cp));
        if (starter_pos) |sp| {
            const blocked = if (cp_ccc == 0)
                (last_ccc != -1)
            else
                (last_ccc >= cp_ccc);

            if (!blocked) {
                if (compose(items[sp], cp)) |composite| {
                    items[sp] = composite;
                    // Keep starter's original src offset on the composite.
                    continue;
                }
            }
        }
        items[out_len] = cp;
        src_items[out_len] = sof;
        if (cp_ccc == 0) {
            starter_pos = out_len;
            last_ccc = -1;
        } else {
            last_ccc = cp_ccc;
        }
        out_len += 1;
    }
    buf.shrinkRetainingCapacity(out_len);
    src.shrinkRetainingCapacity(out_len);
}

fn composeInPlace(buf: *std.ArrayList(u21)) void {
    const items = buf.items;
    if (items.len == 0) return;
    var out_len: usize = 0;
    var starter_pos: ?usize = null; // index in items of last starter we may still extend
    var last_ccc: i16 = -1; // -1 sentinel = none yet since last starter
    var i: usize = 0;
    while (i < items.len) : (i += 1) {
        const cp = items[i];
        const cp_ccc: i16 = @intCast(ccc(cp));
        if (starter_pos) |sp| {
            // Try to compose items[sp] with cp.
            // "Blocked" if there is a previous char with ccc >= cp_ccc and cp_ccc != 0,
            // or cp_ccc == 0 and last_ccc != -1 (intervening combining mark of any ccc would
            // technically not block, but a non-starter sequence between starter and another
            // starter means the new starter cannot compose with the old).
            const blocked = if (cp_ccc == 0)
                // For starter-starter composition, blocked iff there are any non-starters in between.
                (last_ccc != -1)
            else
                (last_ccc >= cp_ccc);

            if (!blocked) {
                if (compose(items[sp], cp)) |composite| {
                    items[sp] = composite;
                    // Do not emit cp; do not update last_ccc.
                    continue;
                }
            }
        }
        // Emit cp.
        items[out_len] = cp;
        if (cp_ccc == 0) {
            starter_pos = out_len;
            last_ccc = -1;
        } else {
            last_ccc = cp_ccc;
        }
        out_len += 1;
    }
    buf.shrinkRetainingCapacity(out_len);
}

// ============================================================
// Tests
// ============================================================

const testing = std.testing;

test "ccc lookup basic" {
    try testing.expectEqual(@as(u8, 0), ccc('a'));
    try testing.expectEqual(@as(u8, 230), ccc(0x0301)); // combining acute
    try testing.expectEqual(@as(u8, 220), ccc(0x0323)); // combining dot below
    try testing.expectEqual(@as(u8, 216), ccc(0x031B)); // combining horn
}

test "decomposeCanonical: precomposed e-acute" {
    const d = decomposeCanonical(0x00E9);
    try testing.expectEqual(@as(usize, 2), d.len);
    try testing.expectEqual(@as(u21, 'e'), d[0]);
    try testing.expectEqual(@as(u21, 0x0301), d[1]);
}

test "compose: e + acute -> e-acute" {
    try testing.expectEqual(@as(?u21, 0x00E9), compose('e', 0x0301));
    try testing.expectEqual(@as(?u21, null), compose('e', 'x'));
}

test "NFC: composed e-acute round-trips" {
    const input = "\xC3\xA9"; // U+00E9
    const out = try normalize(testing.allocator, .nfc, input);
    defer testing.allocator.free(out);
    try testing.expectEqualStrings(input, out);
}

test "NFC: decomposed e + acute recomposes to U+00E9" {
    const input = "e\xCC\x81"; // 'e' + U+0301
    const out = try normalize(testing.allocator, .nfc, input);
    defer testing.allocator.free(out);
    try testing.expectEqualStrings("\xC3\xA9", out);
}

test "NFD: precomposed e-acute decomposes" {
    const input = "\xC3\xA9";
    const out = try normalize(testing.allocator, .nfd, input);
    defer testing.allocator.free(out);
    try testing.expectEqualStrings("e\xCC\x81", out);
}

test "NFKC unwraps compat ligature fi" {
    const input = "\xEF\xAC\x81"; // U+FB01
    const out = try normalize(testing.allocator, .nfkc, input);
    defer testing.allocator.free(out);
    try testing.expectEqualStrings("fi", out);
}

test "Hangul: composed han round-trips through NFD then NFC" {
    const han = "\xED\x95\x9C"; // U+D55C
    const nfd_out = try normalize(testing.allocator, .nfd, han);
    defer testing.allocator.free(nfd_out);
    // 0x1112 0x1161 0x11AB
    const expected_nfd = "\xE1\x84\x92\xE1\x85\xA1\xE1\x86\xAB";
    try testing.expectEqualStrings(expected_nfd, nfd_out);
    const nfc_out = try normalize(testing.allocator, .nfc, nfd_out);
    defer testing.allocator.free(nfc_out);
    try testing.expectEqualStrings(han, nfc_out);
}

test "Combining mark reorder: horn (216) + grave (230) stays in order" {
    // a + 0x031B (216) + 0x0300 (230) — already canonical order, no reorder.
    const input = "a\xCC\x9B\xCC\x80";
    const out = try normalize(testing.allocator, .nfd, input);
    defer testing.allocator.free(out);
    try testing.expectEqualStrings(input, out);
}

test "Combining mark reorder: grave (230) + horn (216) -> horn first" {
    // a + 0x0300 (230) + 0x031B (216) — must reorder to horn-first.
    const input = "a\xCC\x80\xCC\x9B";
    const expected = "a\xCC\x9B\xCC\x80";
    const out = try normalize(testing.allocator, .nfd, input);
    defer testing.allocator.free(out);
    try testing.expectEqualStrings(expected, out);
}

test "NFC: ASCII passes through" {
    const input = "Hello, world!";
    const out = try normalize(testing.allocator, .nfc, input);
    defer testing.allocator.free(out);
    try testing.expectEqualStrings(input, out);
}

test "NFKC: full-width digits to ASCII" {
    // U+FF11 ('1' full-width) -> '1'
    const input = "\xEF\xBC\x91\xEF\xBC\x92\xEF\xBC\x93";
    const out = try normalize(testing.allocator, .nfkc, input);
    defer testing.allocator.free(out);
    try testing.expectEqualStrings("123", out);
}

// Optional conformance test against NormalizationTest.txt.
// Embedded only if the file is present in /tmp; otherwise skipped.
test "conformance: first 200 lines of NormalizationTest.txt" {
    const io = std.Io.Threaded.global_single_threaded.io();
    const data = std.Io.Dir.cwd().readFileAlloc(
        io,
        "/tmp/NormalizationTest.txt",
        testing.allocator,
        .limited(8 * 1024 * 1024),
    ) catch return error.SkipZigTest;
    defer testing.allocator.free(data);

    var line_iter = std.mem.splitScalar(u8, data, '\n');
    var checked: usize = 0;
    var failures: usize = 0;

    while (line_iter.next()) |raw_line| {
        if (checked >= 200) break;
        // Strip comment and trim
        var line = raw_line;
        if (std.mem.indexOfScalar(u8, line, '#')) |hash| line = line[0..hash];
        line = std.mem.trim(u8, line, " \t\r");
        if (line.len == 0) continue;
        if (line[0] == '@') continue;

        // Parse the five semicolon-separated columns.
        var cols: [5][]const u8 = undefined;
        var col_iter = std.mem.splitScalar(u8, line, ';');
        var idx: usize = 0;
        while (col_iter.next()) |c| : (idx += 1) {
            if (idx >= 5) break;
            cols[idx] = c;
        }
        if (idx < 5) continue;

        const src = try parseCps(testing.allocator, cols[0]);
        defer testing.allocator.free(src);
        const c2 = try parseCps(testing.allocator, cols[1]);
        defer testing.allocator.free(c2);
        const c3 = try parseCps(testing.allocator, cols[2]);
        defer testing.allocator.free(c3);
        const c4 = try parseCps(testing.allocator, cols[3]);
        defer testing.allocator.free(c4);
        const c5 = try parseCps(testing.allocator, cols[4]);
        defer testing.allocator.free(c5);

        const src_utf8 = try cpsToUtf8(testing.allocator, src);
        defer testing.allocator.free(src_utf8);

        const got_nfc = try normalize(testing.allocator, .nfc, src_utf8);
        defer testing.allocator.free(got_nfc);
        const got_nfd = try normalize(testing.allocator, .nfd, src_utf8);
        defer testing.allocator.free(got_nfd);
        const got_nfkc = try normalize(testing.allocator, .nfkc, src_utf8);
        defer testing.allocator.free(got_nfkc);
        const got_nfkd = try normalize(testing.allocator, .nfkd, src_utf8);
        defer testing.allocator.free(got_nfkd);

        const exp_nfc = try cpsToUtf8(testing.allocator, c2);
        defer testing.allocator.free(exp_nfc);
        const exp_nfd = try cpsToUtf8(testing.allocator, c3);
        defer testing.allocator.free(exp_nfd);
        const exp_nfkc = try cpsToUtf8(testing.allocator, c4);
        defer testing.allocator.free(exp_nfkc);
        const exp_nfkd = try cpsToUtf8(testing.allocator, c5);
        defer testing.allocator.free(exp_nfkd);

        if (!std.mem.eql(u8, got_nfc, exp_nfc)) failures += 1;
        if (!std.mem.eql(u8, got_nfd, exp_nfd)) failures += 1;
        if (!std.mem.eql(u8, got_nfkc, exp_nfkc)) failures += 1;
        if (!std.mem.eql(u8, got_nfkd, exp_nfkd)) failures += 1;

        checked += 1;
    }

    if (failures != 0) {
        std.debug.print("conformance failures: {d} across {d} lines\n", .{ failures, checked });
    }
    try testing.expectEqual(@as(usize, 0), failures);
}

fn parseCps(allocator: std.mem.Allocator, s: []const u8) ![]u21 {
    var list: std.ArrayList(u21) = .empty;
    defer list.deinit(allocator);
    var it = std.mem.tokenizeScalar(u8, std.mem.trim(u8, s, " \t\r"), ' ');
    while (it.next()) |tok| {
        const cp = try std.fmt.parseInt(u21, tok, 16);
        try list.append(allocator, cp);
    }
    return list.toOwnedSlice(allocator);
}

fn cpsToUtf8(allocator: std.mem.Allocator, cps: []const u21) ![]u8 {
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    var buf: [4]u8 = undefined;
    for (cps) |cp| {
        const n = try std.unicode.utf8Encode(@intCast(cp), &buf);
        try out.appendSlice(allocator, buf[0..n]);
    }
    return out.toOwnedSlice(allocator);
}
